#!/usr/bin/env bash
# Harness 1: STT stress (base.en + large-v3-turbo, first-load + per-utterance latency).
# Audio is generated by gen-utterances.py; transcription runs in the ignored Rust test.
set -euo pipefail
cd "$(dirname "$0")/../.." || exit 2

mkdir -p scripts/stress/out

python3 scripts/stress/gen-utterances.py

export XENON_STT_DIR="$PWD/scripts/stress/out/stt"

cd src-tauri
cargo test --bin xenon stress_stt_harness -- --ignored --nocapture 2>&1 | tee ../scripts/stress/out/stt.log | tail -n 40